-- =====================================================================
-- 054 · 8.2 Información para mujeres (Res. 1519 de 2020 · grupos de interés)
--  La página «8.2 Información para mujeres» estaba publicada pero vacía.
--  Se publica contenido útil y conforme: servicios de salud de la mujer,
--  atención a víctimas de violencia (Res. 459/2012, Ley 1257/2008) y
--  enlaces oficiales (Ministerio de Igualdad, Minsalud). No borra nada.
-- =====================================================================
SET NAMES utf8mb4;
SET time_zone = '+00:00';

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, orden, migrado_de)
SELECT p.id, 'Salud y derechos de las mujeres', 'informacion-para-mujeres-salud-y-derechos', 'Servicios de salud para la mujer, atención a víctimas de violencia y enlaces oficiales.',
  '<p>La E.S.E. Hospital San José del Guaviare reconoce a las mujeres como sujetos de especial protección y pone a su disposición servicios de salud y canales de orientación para el cuidado de su bienestar y la garantía de sus derechos.</p><h2>Salud de la mujer</h2><p>A través de su portafolio, la E.S.E. presta servicios orientados a la salud de la mujer en todas las etapas de su vida:</p><ul><li>Control prenatal y atención materno-perinatal.</li><li>Planificación familiar y asesoría en métodos anticonceptivos.</li><li>Tamizaje de cáncer de cuello uterino (citología y prueba de VPH) y de mama.</li><li>Salud sexual y reproductiva con enfoque de derechos.</li><li>Atención del parto, puerperio y del recién nacido.</li></ul><p>Consulte el <a href="/portafolio-de-servicios">portafolio de servicios</a> y <a href="/atencion-y-servicios-a-la-ciudadania/canales-de-atencion">solicite su cita</a>.</p><h2>Atención a mujeres víctimas de violencia</h2><p>La atención en salud a víctimas de violencia sexual es urgente y prioritaria: se presta las 24 horas en el servicio de urgencias, es gratuita y <strong>no requiere denuncia previa</strong>, conforme a la <strong>Resolución 459 de 2012</strong> del Ministerio de Salud (Protocolo de atención integral en salud para víctimas de violencia sexual) y la <strong>Ley 1257 de 2008</strong>.</p><p>Líneas nacionales de orientación y denuncia:</p><ul><li><strong>Línea 155</strong> — orientación a mujeres víctimas de violencia (gratuita y nacional).</li><li><strong>Línea 122</strong> — Fiscalía General de la Nación (denuncias).</li><li><strong>Línea 123</strong> — emergencias.</li></ul><h2>Derechos y enlaces oficiales</h2><ul><li><a href="https://www.minigualdad.gov.co/" target="_blank" rel="noopener">Ministerio de Igualdad y Equidad</a></li><li><a href="https://www.minsalud.gov.co/salud/publica/ssr/Paginas/Salud-sexual-y-reproductiva.aspx" target="_blank" rel="noopener">Ministerio de Salud — Salud sexual y reproductiva</a></li></ul><p>Para presentar peticiones, quejas, reclamos o denuncias ante la E.S.E., utilice el canal de <a href="/pqrsf">PQRSFD</a>.</p>',
  'articulo', 'Grupos de interés', 'publicada', 0, 'E.S.E. Hospital San José del Guaviare', '2026-11-05 12:00:00', 0, 'Res. 1519 de 2020 — 8.2 Información para mujeres (grupos de interés)'
  FROM cms_paginas p WHERE p.slug = 'informacion-para-mujeres'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas x JOIN cms_paginas q ON q.id = x.pagina_id WHERE q.slug = 'informacion-para-mujeres' AND x.slug = 'informacion-para-mujeres-salud-y-derechos');
